1	package com.example.starter.ride;
2	
3	import java.time.Clock;
4	import java.time.Instant;
5	import java.time.LocalDate;
6	import java.util.ArrayList;
7	import java.util.Arrays;
8	import java.util.LinkedHashMap;
9	import java.util.List;
10	import java.util.Map;
11	
12	import org.springframework.stereotype.Service;
13	import org.springframework.transaction.annotation.Transactional;
14	
15	import com.example.starter.ride.Idempotency.ApiResult;
16	import com.example.starter.ride.dto.RideDtos.ArchiveRequest;
17	import com.example.starter.ride.dto.RideDtos.CheckItem;
18	import com.example.starter.ride.dto.RideDtos.CreateRideRequest;
19	import com.example.starter.ride.dto.RideDtos.DailyCheckRequest;
20	import com.example.starter.ride.dto.RideDtos.IssueCertificateRequest;
21	import com.example.starter.ride.dto.RideDtos.OpenRequest;
22	import com.example.starter.ride.dto.RideDtos.OverhaulRequest;
23	import com.example.starter.ride.dto.RideDtos.ReadingRequest;
24	import com.example.starter.ride.dto.RideDtos.RecheckRequest;
25	import com.example.starter.ride.dto.RideDtos.ReopenRequest;
26	import com.example.starter.ride.dto.RideDtos.RevokeCertificateRequest;
27	import com.example.starter.ride.dto.RideDtos.SafetyFaultRequest;
28	import com.example.starter.ride.dto.RideDtos.SupervisionConfirmRequest;
29	import com.example.starter.ride.dto.RideDtos.TrialRunRequest;
30	import com.fasterxml.jackson.databind.ObjectMapper;
31	
32	/**
33	 * 游乐设施日检与载客联锁核心服务。
34	 * 状态链：日检→试运行(恰3次)→开放→运行监测→闭园归档；
35	 * 故障停运/缓停→复检合格→复开(同日恰2次合法)。
36	 * 所有状态流转在事务内持行锁串行执行，保证同一设备同时刻只有一条状态链。
37	 */
38	@Service
39	public class RideService {
40	
41	    private final RideRepository rides;
42	    private final RideRecordRepository records;
43	    private final CertificateRepository certificates;
44	    private final SupervisionRepository supervisions;
45	    private final Idempotency.Executor idempotency;
46	    private final ObjectMapper objectMapper;
47	    private final Clock clock;
48	
49	    public RideService(RideRepository rides, RideRecordRepository records,
50	            CertificateRepository certificates, SupervisionRepository supervisions,
51	            Idempotency.Executor idempotency, ObjectMapper objectMapper, Clock clock) {
52	        this.rides = rides;
53	        this.records = records;
54	        this.certificates = certificates;
55	        this.supervisions = supervisions;
56	        this.idempotency = idempotency;
57	        this.objectMapper = objectMapper;
58	        this.clock = clock;
59	    }
60	
61	    /** 创建设备（合成数据），初始状态为待日检；inspectionRequired 缺省 false，旧设备行为不变。 */
62	    @Transactional
63	    public Map<String, Object> createRide(CreateRideRequest request) {
64	        boolean inspectionRequired = Boolean.TRUE.equals(request.inspectionRequired());
65	        Ride ride = rides.insert(request.name(), request.maxLoad(), request.maxSpeed(),
66	                inspectionRequired);
67	        records.insertEvent(ride.id(), "CREATE", "设备登记：" + ride.name()
68	                + (inspectionRequired ? "（受检设备）" : ""));
69	        return rideView(ride);
70	    }
71	
72	    /** 日检：清单逐项合格方可试运行；安全装置任一失效整机立即停运。 */
73	    public ApiResult dailyCheck(long rideId, DailyCheckRequest request) {
74	        return idempotency.execute(request.requestId(), "DAILY_CHECK", rideId, request, () -> {
75	            Ride ride = lock(rideId);
76	            requireStatus(ride, "当前状态不允许日检",
77	                    RideStatus.PENDING_CHECK, RideStatus.CHECKED);
78	            boolean allPassed = request.items().stream().allMatch(CheckItem::passed);
79	            List<String> failedSafety = request.items().stream()
80	                    .filter(item -> !item.passed() && isSafetyDevice(item.itemName()))
81	                    .map(CheckItem::itemName)
82	                    .toList();
83	            LocalDate today = LocalDate.now(clock);
84	            records.insertDailyCheck(rideId, request.requestId(), today, allPassed, request.items());
85	            records.insertEvent(rideId, "DAILY_CHECK",
86	                    allPassed ? "日检清单逐项合格" : "日检存在不合格项");
87	
88	            RideStatus newStatus = ride.status();
89	            LocalDate checkDate = ride.checkDate();
90	            int trialCount = ride.trialCount();
91	            if (allPassed) {
92	                newStatus = RideStatus.CHECKED;
93	                checkDate = today;
94	                trialCount = 0;
95	            } else if (!failedSafety.isEmpty()) {
96	                newStatus = RideStatus.STOPPED;
97	                records.insertEvent(rideId, "FAULT_STOP",
98	                        "安全装置失效立即停运：" + String.join("、", failedSafety));
99	            }
100	            update(ride, newStatus, trialCount, ride.reopenCount(), checkDate, ride.reopenDate());
101	
102	            Map<String, Object> body = rideView(rideId);
103	            body.put("allPassed", allPassed);
104	            body.put("checkDate", allPassed ? today.toString() : null);
105	            return ok(body);
106	        });
107	    }
108	
109	    /** 试运行：恰3次空载无异常方可载客；任一次异常立即故障停运。 */
110	    public ApiResult trialRun(long rideId, TrialRunRequest request) {
111	        return idempotency.execute(request.requestId(), "TRIAL_RUN", rideId, request, () -> {
112	            Ride ride = lock(rideId);
113	            requireStatus(ride, "日检合格后方可试运行", RideStatus.CHECKED);
114	            int seq = ride.trialCount() + 1;
115	            records.insertTrialRun(rideId, request.requestId(), seq, request.normal());
116	
117	            RideStatus newStatus = RideStatus.CHECKED;
118	            int trialCount = ride.trialCount();
119	            if (request.normal()) {
120	                trialCount = seq;
121	                records.insertEvent(rideId, "TRIAL_RUN", "第" + seq + "次空载试运行正常");
122	                if (trialCount == Ride.REQUIRED_TRIAL_COUNT) {
123	                    newStatus = RideStatus.READY;
124	                    records.insertEvent(rideId, "TRIAL_RUN", "试运行恰3次合格，允许开放载客");
125	                }
126	            } else {
127	                newStatus = RideStatus.STOPPED;
128	                trialCount = 0;
129	                records.insertEvent(rideId, "FAULT_STOP", "第" + seq + "次试运行异常，整机立即停运");
130	            }
131	            update(ride, newStatus, trialCount, ride.reopenCount(),
132	                    ride.checkDate(), ride.reopenDate());
133	            return ok(rideView(rideId));
134	        });
135	    }
136	
137	    /** 开放：须当日日检合格且试运行恰3次合格；未日检设备无法开放；并发开放唯一成功；
138	     * 受检设备还须持当前有效年度证书且完成当前大修版本监督检验。 */
139	    public ApiResult open(long rideId, OpenRequest request) {
140	        return idempotency.execute(request.requestId(), "OPEN", rideId, request, () -> {
141	            Ride ride = lock(rideId);
142	            if (ride.checkDate() == null || !ride.checkDate().equals(LocalDate.now(clock))) {
143	                throw ApiException.conflict("未日检设备无法开放");
144	            }
145	            requireStatus(ride, "当前状态不允许开放，须试运行恰3次合格",
146	                    RideStatus.READY);
147	            requireInspectionEligibility(ride);
148	            update(ride, RideStatus.OPEN, ride.trialCount(), ride.reopenCount(),
149	                    ride.checkDate(), ride.reopenDate());
150	            records.insertEvent(rideId, "OPEN", "设备开放载客");
151	            return ok(rideView(rideId));
152	        });
153	    }
154	
155	    /** 安全装置失效上报：压杠、安全带与联锁装置任一失效整机立即停运。 */
156	    public ApiResult safetyFault(long rideId, SafetyFaultRequest request) {
157	        return idempotency.execute(request.requestId(), "SAFETY_FAULT", rideId, request, () -> {
158	            if (!isSafetyDevice(request.device())) {
159	                throw ApiException.unprocessable("未知安全装置：" + request.device()
160	                        + "，合法值为压杠/安全带/联锁装置");
161	            }
162	            Ride ride = lock(rideId);
163	            if (ride.status() == RideStatus.ARCHIVED) {
164	                throw ApiException.conflict("设备已归档，拒绝安全装置失效上报");
165	            }
166	            if (ride.status() == RideStatus.STOPPED) {
167	                Map<String, Object> body = rideView(rideId);
168	                body.put("message", "设备已处于故障停运状态");
169	                return ok(body);
170	            }
171	            requireStatus(ride, "设备未在运行流程中，无法上报安全装置失效",
172	                    RideStatus.CHECKED, RideStatus.READY, RideStatus.OPEN,
173	                    RideStatus.SUSPENDED, RideStatus.RECHECKED);
174	            update(ride, RideStatus.STOPPED, ride.trialCount(), ride.reopenCount(),
175	                    ride.checkDate(), ride.reopenDate());
176	            records.insertEvent(rideId, "FAULT_STOP",
177	                    "安全装置失效立即停运：" + request.device());
178	            return ok(rideView(rideId));
179	        });
180	    }
181	
182	    /** 复检：故障停运或缓停后复检合格方可复开。 */
183	    public ApiResult recheck(long rideId, RecheckRequest request) {
184	        return idempotency.execute(request.requestId(), "RECHECK", rideId, request, () -> {
185	            Ride ride = lock(rideId);
186	            requireStatus(ride, "仅故障停运或缓停设备可复检",
187	                    RideStatus.STOPPED, RideStatus.SUSPENDED);
188	            boolean allPassed = request.items().stream().allMatch(CheckItem::passed);
189	            if (allPassed) {
190	                update(ride, RideStatus.RECHECKED, ride.trialCount(), ride.reopenCount(),
191	                        ride.checkDate(), ride.reopenDate());
192	                records.insertEvent(rideId, "RECHECK", "复检合格，允许复开");
193	            } else {
194	                List<String> failed = request.items().stream()
195	                        .filter(item -> !item.passed())
196	                        .map(CheckItem::itemName)
197	                        .toList();
198	                records.insertEvent(rideId, "RECHECK",
199	                        "复检不合格：" + String.join("、", failed));
200	            }
201	            Map<String, Object> body = rideView(rideId);
202	            body.put("allPassed", allPassed);
203	            return ok(body);
204	        });
205	    }
206	
207	    /** 复开：同日复开最多2次，恰2次合法，超出当日禁开；受检设备还须满足年度证书与监督检验门禁。 */
208	    public ApiResult reopen(long rideId, ReopenRequest request) {
209	        return idempotency.execute(request.requestId(), "REOPEN", rideId, request, () -> {
210	            Ride ride = lock(rideId);
211	            requireStatus(ride, "仅复检合格设备可复开", RideStatus.RECHECKED);
212	            LocalDate today = LocalDate.now(clock);
213	            int used = today.equals(ride.reopenDate()) ? ride.reopenCount() : 0;
214	            if (used >= Ride.MAX_DAILY_REOPEN) {
215	                throw ApiException.unprocessable(
216	                        "同日复开已达上限" + Ride.MAX_DAILY_REOPEN + "次，当日禁开");
217	            }
218	            requireInspectionEligibility(ride);
219	            int reopenCount = used + 1;
220	            update(ride, RideStatus.OPEN, ride.trialCount(), reopenCount,
221	                    ride.checkDate(), today);
222	            records.insertEvent(rideId, "REOPEN", "当日第" + reopenCount + "次复开");
223	            return ok(rideView(rideId));
224	        });
225	    }
226	
227	    /** 闭园归档：终态；重复归档返回幂等成功；归档后迟到运行数据只记迟到事件。 */
228	    public ApiResult archive(long rideId, ArchiveRequest request) {
229	        return idempotency.execute(request.requestId(), "ARCHIVE", rideId, request, () -> {
230	            Ride ride = lock(rideId);
231	            if (ride.status() == RideStatus.ARCHIVED) {
232	                Map<String, Object> body = rideView(rideId);
233	                body.put("message", "设备已归档，重复归档幂等成功");
234	                return ok(body);
235	            }
236	            update(ride, RideStatus.ARCHIVED, ride.trialCount(), ride.reopenCount(),
237	                    ride.checkDate(), ride.reopenDate());
238	            records.insertEvent(rideId, "ARCHIVE", "闭园归档，进入终态");
239	            return ok(rideView(rideId));
240	        });
241	    }
242	
243	    /**
244	     * 运行监测读数：载荷或速度超阈值触发缓停，恰等阈值合格；
245	     * 归档后迟到数据只记迟到事件，不改变状态。
246	     */
247	    @Transactional
248	    public Map<String, Object> reading(long rideId, ReadingRequest request) {
249	        Ride ride = lock(rideId);
250	        if (ride.status() == RideStatus.ARCHIVED) {
251	            records.insertReading(rideId, request.loadValue(), request.speedValue(), false, true);
252	            records.insertEvent(rideId, "LATE_READING",
253	                    "归档后迟到运行数据：载荷=" + request.loadValue()
254	                            + "，速度=" + request.speedValue());
255	            Map<String, Object> body = rideView(ride);
256	            body.put("late", true);
257	            body.put("message", "设备已归档，迟到数据仅记录事件");
258	            return body;
259	        }
260	        if (ride.status() != RideStatus.OPEN) {
261	            throw ApiException.conflict("设备未开放，拒绝运行监测读数");
262	        }
263	        boolean exceeded = request.loadValue() > ride.maxLoad()
264	                || request.speedValue() > ride.maxSpeed();
265	        records.insertReading(rideId, request.loadValue(), request.speedValue(), exceeded, false);
266	        // 受检设备证书失效（过期/恰截止/撤销/缺失）：载客读数只记录并告警，不以正常读数恢复资格
267	        boolean certificateInvalid = ride.inspectionRequired() && !certificateValidNow(rideId);
268	        if (certificateInvalid) {
269	            records.insertEvent(rideId, "CERT_EXPIRED_ALARM",
270	                    "年度证书已失效，载客读数仅记录并告警：载荷=" + request.loadValue()
271	                            + "，速度=" + request.speedValue());
272	        }
273	        if (exceeded) {
274	            update(ride, RideStatus.SUSPENDED, ride.trialCount(), ride.reopenCount(),
275	                    ride.checkDate(), ride.reopenDate());
276	            records.insertEvent(rideId, "SLOW_STOP",
277	                    "载荷或速度超阈值触发缓停：载荷=" + request.loadValue()
278	                            + "/" + ride.maxLoad() + "，速度=" + request.speedValue()
279	                            + "/" + ride.maxSpeed());
280	        } else {
281	            records.insertEvent(rideId, "READING",
282	                    "运行读数合格：载荷=" + request.loadValue()
283	                            + "，速度=" + request.speedValue());
284	        }
285	        Map<String, Object> body = rideView(rideId);
286	        body.put("exceeded", exceeded);
287	        if (certificateInvalid) {
288	            body.put("alarm", true);
289	            body.put("certificateValid", false);
290	        }
291	        return body;
292	    }
293	
294	    /** 查询设备当前状态。 */
295	    @Transactional(readOnly = true)
296	    public Map<String, Object> getRide(long rideId) {
297	        return rideView(rides.findById(rideId)
298	                .orElseThrow(() -> ApiException.notFound("设备不存在：" + rideId)));
299	    }
300	
301	    /** 启停链事件，可复算。 */
302	    @Transactional(readOnly = true)
303	    public List<Map<String, Object>> listEvents(long rideId) {
304	        ensureExists(rideId);
305	        return records.listEvents(rideId);
306	    }
307	
308	    /** 日检清单（含明细），可复算。 */
309	    @Transactional(readOnly = true)
310	    public List<Map<String, Object>> listDailyChecks(long rideId) {
311	        ensureExists(rideId);
312	        List<Map<String, Object>> checks = records.listDailyChecks(rideId);
313	        for (Map<String, Object> check : checks) {
314	            long checkId = ((Number) check.get("id")).longValue();
315	            check.put("items", records.listDailyCheckItems(checkId));
316	        }
317	        return checks;
318	    }
319	
320	    /** 试运行记录，可复算。 */
321	    @Transactional(readOnly = true)
322	    public List<Map<String, Object>> listTrialRuns(long rideId) {
323	        ensureExists(rideId);
324	        return records.listTrialRuns(rideId);
325	    }
326	
327	    /** 运行读数记录。 */
328	    @Transactional(readOnly = true)
329	    public List<Map<String, Object>> listReadings(long rideId) {
330	        ensureExists(rideId);
331	        return records.listReadings(rideId);
332	    }
333	
334	    /**
335	     * 签发/换证：固定设备编号、检验合格时刻与有效截止（默认合格时刻+365×24小时，恰截止失效）；
336	     * 换证原子切换唯一当前指针，历史证书不可覆盖。
337	     */
338	    public ApiResult issueCertificate(long rideId, IssueCertificateRequest request) {
339	        return idempotency.execute(request.requestId(), "CERT_ISSUE", rideId, request, () -> {
340	            Ride ride = lock(rideId);
341	            requireInspectionRequired(ride);
342	            Instant passedAt = request.passedAt() != null ? request.passedAt()
343	                    : Instant.now(clock);
344	            Instant validUntil = request.validUntil() != null ? request.validUntil()
345	                    : passedAt.plus(Ride.CERT_DEFAULT_VALIDITY);
346	            if (!validUntil.isAfter(passedAt)) {
347	                throw ApiException.unprocessable("有效截止必须晚于检验合格时刻");
348	            }
349	            long certId = certificates.insert(rideId, request.requestId(), passedAt, validUntil);
350	            certificates.switchCurrent(rideId, certId);
351	            records.insertEvent(rideId, "CERT_ISSUE",
352	                    "签发年度证书#" + certId + "，检验合格时刻=" + passedAt
353	                            + "，有效截止=" + validUntil);
354	            return ok(certificateView(certificates.findById(certId).orElseThrow()));
355	        });
356	    }
357	
358	    /** 撤销当前证书：携带 expectedVersion 乐观锁，成功版本加1；撤销后设备无当前证书。 */
359	    public ApiResult revokeCertificate(long rideId, RevokeCertificateRequest request) {
360	        return idempotency.execute(request.requestId(), "CERT_REVOKE", rideId, request, () -> {
361	            lock(rideId);
362	            Certificate current = certificates.findCurrent(rideId)
363	                    .orElseThrow(() -> ApiException.notFound(
364	                            "设备当前无年度证书可撤销：" + rideId));
365	            if (current.version() != request.expectedVersion()) {
366	                throw ApiException.conflict("证书版本冲突：expectedVersion="
367	                        + request.expectedVersion() + "，当前版本=" + current.version());
368	            }
369	            if (!certificates.revoke(current.id(), request.expectedVersion(),
370	                    request.reason(), Instant.now(clock))) {
371	                throw ApiException.conflict("证书并发变更，请重试");
372	            }
373	            certificates.clearCurrent(rideId);
374	            records.insertEvent(rideId, "CERT_REVOKE", "撤销年度证书#" + current.id()
375	                    + (request.reason() == null ? "" : "，原因：" + request.reason()));
376	            return ok(certificateView(certificates.findById(current.id()).orElseThrow()));
377	        });
378	    }
379	
380	    /**
381	     * 登记大修：原子递增大修版本（检验周期版本）、开放中设备暂停开放、旧监督检验随之失效；
382	     * 旧年度证书可查但不足以复开，须重新完成当前版本监督检验。
383	     */
384	    public ApiResult registerOverhaul(long rideId, OverhaulRequest request) {
385	        return idempotency.execute(request.requestId(), "OVERHAUL", rideId, request, () -> {
386	            Ride ride = lock(rideId);
387	            requireInspectionRequired(ride);
388	            if (ride.status() == RideStatus.ARCHIVED) {
389	                throw ApiException.unprocessable("设备已归档，拒绝登记大修");
390	            }
391	            long newOverhaulVersion = ride.overhaulVersion() + 1;
392	            RideStatus newStatus = ride.status() == RideStatus.OPEN
393	                    ? RideStatus.SUSPENDED : ride.status();
394	            if (!rides.registerOverhaul(ride, newStatus, newOverhaulVersion)) {
395	                throw ApiException.conflict("设备状态并发变更，请重试");
396	            }
397	            supervisions.insertOverhaul(rideId, request.requestId(), newOverhaulVersion);
398	            records.insertEvent(rideId, "OVERHAUL",
399	                    "登记大修，检验周期版本升至" + newOverhaulVersion + "，旧监督检验失效"
400	                            + (newStatus != ride.status() ? "，开放中设备暂停开放" : ""));
401	            Map<String, Object> body = rideView(rideId);
402	            body.put("overhaulVersion", newOverhaulVersion);
403	            return ok(body);
404	        });
405	    }
406	
407	    /**
408	     * 监督检验确认：须绑定当前大修版本，两名不同检验人共同确认全清单合格；
409	     * 确认后只恢复开放资格，不自动开放，也不重置原当日复开次数。
410	     */
411	    public ApiResult confirmSupervision(long rideId, SupervisionConfirmRequest request) {
412	        return idempotency.execute(request.requestId(), "SUPERVISION", rideId, request, () -> {
413	            Ride ride = lock(rideId);
414	            requireInspectionRequired(ride);
415	            if (request.overhaulVersion() != ride.overhaulVersion()) {
416	                throw ApiException.unprocessable("监督检验须绑定当前大修版本：请求="
417	                        + request.overhaulVersion() + "，当前=" + ride.overhaulVersion());
418	            }
419	            if (request.inspectorOne().equals(request.inspectorTwo())) {
420	                throw ApiException.unprocessable("两名检验人必须不同，不得同一人确认");
421	            }
422	            if (!request.items().stream().allMatch(CheckItem::passed)) {
423	                throw ApiException.unprocessable("监督检验须全清单合格方可确认");
424	            }
425	            long inspectionId = supervisions.insertInspection(rideId, request.requestId(),
426	                    request.overhaulVersion(), request.inspectorOne(), request.inspectorTwo(),
427	                    request.items());
428	            records.insertEvent(rideId, "SUPERVISION",
429	                    "监督检验确认：绑定大修版本" + request.overhaulVersion() + "，检验人="
430	                            + request.inspectorOne() + "、" + request.inspectorTwo()
431	                            + "，全清单合格，恢复开放资格（不自动开放）");
432	            Map<String, Object> body = rideView(rideId);
433	            body.put("inspectionId", inspectionId);
434	            body.put("allPassed", true);
435	            return ok(body);
436	        });
437	    }
438	
439	    /** 设备全部年度证书（含历史与已撤销），历史证书不可覆盖、可复算。 */
440	    @Transactional(readOnly = true)
441	    public List<Map<String, Object>> listCertificates(long rideId) {
442	        ensureExists(rideId);
443	        return certificates.listByRide(rideId).stream().map(this::certificateView).toList();
444	    }
445	
446	    /** 当前年度证书；无当前证书返回404。 */
447	    @Transactional(readOnly = true)
448	    public Map<String, Object> getCurrentCertificate(long rideId) {
449	        ensureExists(rideId);
450	        return certificateView(certificates.findCurrent(rideId)
451	                .orElseThrow(() -> ApiException.notFound("设备当前无年度证书：" + rideId)));
452	    }
453	
454	    /** 撤销证据：设备全部已撤销证书。 */
455	    @Transactional(readOnly = true)
456	    public List<Map<String, Object>> listRevocations(long rideId) {
457	        ensureExists(rideId);
458	        return certificates.listByRide(rideId).stream()
459	                .filter(Certificate::revoked)
460	                .map(this::certificateView)
461	                .toList();
462	    }
463	
464	    /** 大修登记记录，可复算。 */
465	    @Transactional(readOnly = true)
466	    public List<Map<String, Object>> listOverhauls(long rideId) {
467	        ensureExists(rideId);
468	        return supervisions.listOverhauls(rideId);
469	    }
470	
471	    /** 监督检验记录（含清单明细），可复算。 */
472	    @Transactional(readOnly = true)
473	    public List<Map<String, Object>> listSupervisions(long rideId) {
474	        ensureExists(rideId);
475	        return supervisions.listInspections(rideId);
476	    }
477	
478	    /** 开放资格证据：证书有效性、监督检验状态与判定原因，可复算。 */
479	    @Transactional(readOnly = true)
480	    public Map<String, Object> getEligibility(long rideId) {
481	        Ride ride = rides.findById(rideId)
482	                .orElseThrow(() -> ApiException.notFound("设备不存在：" + rideId));
483	        Map<String, Object> view = new LinkedHashMap<>();
484	        Instant now = Instant.now(clock);
485	        view.put("rideId", ride.id());
486	        view.put("status", ride.status().name());
487	        view.put("inspectionRequired", ride.inspectionRequired());
488	        view.put("overhaulVersion", ride.overhaulVersion());
489	        view.put("now", now.toString());
490	        List<String> reasons = new ArrayList<>();
491	        boolean eligible = true;
492	        Certificate current = null;
493	        boolean supervisionRequired = false;
494	        boolean supervisionConfirmed = false;
495	        Boolean certificateValid = null;
496	        if (ride.inspectionRequired()) {
497	            current = certificates.findCurrent(rideId).orElse(null);
498	            certificateValid = current != null && current.validAt(now);
499	            if (!certificateValid) {
500	                reasons.add(current == null ? "无当前年度证书" : "年度证书已失效（恰截止失效）");
501	            }
502	            supervisionRequired = ride.overhaulVersion() > 0;
503	            supervisionConfirmed = supervisionRequired
504	                    && supervisions.existsConfirmed(rideId, ride.overhaulVersion());
505	            if (supervisionRequired && !supervisionConfirmed) {
506	                reasons.add("大修后未完成当前大修版本监督检验");
507	            }
508	            eligible = certificateValid && (!supervisionRequired || supervisionConfirmed);
509	        }
510	        view.put("certificateValid", certificateValid);
511	        view.put("supervisionRequired", supervisionRequired);
512	        view.put("supervisionConfirmed", supervisionConfirmed);
513	        view.put("currentCertificate", current == null ? null : certificateView(current));
514	        view.put("openEligible", eligible);
515	        view.put("reasons", reasons);
516	        return view;
517	    }
518	
519	    private void ensureExists(long rideId) {
520	        if (rides.findById(rideId).isEmpty()) {
521	            throw ApiException.notFound("设备不存在：" + rideId);
522	        }
523	    }
524	
525	    private Ride lock(long rideId) {
526	        return rides.findByIdForUpdate(rideId)
527	                .orElseThrow(() -> ApiException.notFound("设备不存在：" + rideId));
528	    }
529	
530	    private void requireStatus(Ride ride, String message, RideStatus... allowed) {
531	        if (Arrays.stream(allowed).noneMatch(s -> s == ride.status())) {
532	            throw ApiException.conflict(message + "（当前状态：" + ride.status() + "）");
533	        }
534	    }
535	
536	    private void update(Ride ride, RideStatus status, int trialCount, int reopenCount,
537	            LocalDate checkDate, LocalDate reopenDate) {
538	        if (!rides.updateWithVersion(ride, status, trialCount, reopenCount,
539	                checkDate, reopenDate)) {
540	            throw ApiException.conflict("设备状态并发变更，请重试");
541	        }
542	    }
543	
544	    private boolean isSafetyDevice(String name) {
545	        return Arrays.asList(Ride.SAFETY_DEVICES).contains(name);
546	    }
547	
548	    /** 受检设备开放/复开门禁：当前有效年度证书 + 当前大修版本监督检验，缺一不可。 */
549	    private void requireInspectionEligibility(Ride ride) {
550	        if (!ride.inspectionRequired()) {
551	            return;
552	        }
553	        Certificate current = certificates.findCurrent(ride.id())
554	                .orElseThrow(() -> ApiException.unprocessable(
555	                        "受检设备无当前年度证书，禁止开放或复开"));
556	        if (!current.validAt(Instant.now(clock))) {
557	            throw ApiException.unprocessable("年度证书已失效（恰截止失效），禁止开放或复开");
558	        }
559	        if (ride.overhaulVersion() > 0
560	                && !supervisions.existsConfirmed(ride.id(), ride.overhaulVersion())) {
561	            throw ApiException.unprocessable("大修后未完成当前大修版本监督检验，禁止开放或复开");
562	        }
563	    }
564	
565	    private void requireInspectionRequired(Ride ride) {
566	        if (!ride.inspectionRequired()) {
567	            throw ApiException.unprocessable("设备未启用受检标志，不适用年度检验流程：" + ride.id());
568	        }
569	    }
570	
571	    /** 当前时刻是否存在有效年度证书：无当前证书或已过期（恰截止失效）均为无效。 */
572	    private boolean certificateValidNow(long rideId) {
573	        Instant now = Instant.now(clock);
574	        return certificates.findCurrent(rideId).map(cert -> cert.validAt(now)).orElse(false);
575	    }
576	
577	    private Map<String, Object> certificateView(Certificate cert) {
578	        Map<String, Object> view = new LinkedHashMap<>();
579	        view.put("certificateId", cert.id());
580	        view.put("rideId", cert.rideId());
581	        view.put("passedAt", cert.passedAt().toString());
582	        view.put("validUntil", cert.validUntil().toString());
583	        view.put("revoked", cert.revoked());
584	        view.put("revokedAt", cert.revokedAt() == null ? null : cert.revokedAt().toString());
585	        view.put("revokeReason", cert.revokeReason());
586	        view.put("version", cert.version());
587	        return view;
588	    }
589	
590	    private Map<String, Object> rideView(long rideId) {
591	        return rideView(rides.findById(rideId).orElseThrow());
592	    }
593	
594	    private Map<String, Object> rideView(Ride ride) {
595	        Map<String, Object> view = new LinkedHashMap<>();
596	        view.put("rideId", ride.id());
597	        view.put("name", ride.name());
598	        view.put("status", ride.status().name());
599	        view.put("maxLoad", ride.maxLoad());
600	        view.put("maxSpeed", ride.maxSpeed());
601	        view.put("trialCount", ride.trialCount());
602	        view.put("reopenCount", ride.reopenCount());
603	        view.put("checkDate", ride.checkDate() == null ? null : ride.checkDate().toString());
604	        view.put("inspectionRequired", ride.inspectionRequired());
605	        view.put("overhaulVersion", ride.overhaulVersion());
606	        return view;
607	    }
608	
609	    private ApiResult ok(Map<String, Object> body) {
610	        try {
611	            return new ApiResult(200, objectMapper.writeValueAsString(body));
612	        } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
613	            throw new IllegalStateException("响应序列化失败", e);
614	        }
615	    }
616	}
