1	package com.example.starter.ride;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	import java.util.Optional;
8	
9	import org.springframework.dao.DuplicateKeyException;
10	import org.springframework.http.HttpStatus;
11	import org.springframework.jdbc.core.JdbcTemplate;
12	import org.springframework.stereotype.Repository;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.support.TransactionTemplate;
15	
16	import com.fasterxml.jackson.databind.ObjectMapper;
17	
18	/**
19	 * 幂等组件：指纹覆盖 requestId 与全部业务字段。
20	 * 同键同参返回首次结果，同键异参返回 409 且不改变设备状态；
21	 * 幂等记录与业务写入在同一事务内提交。
22	 */
23	public final class Idempotency {
24	
25	    private Idempotency() {
26	    }
27	
28	    /** 一次幂等执行的最终响应：HTTP 状态码 + JSON 响应体。 */
29	    public record ApiResult(int status, String body) {
30	    }
31	
32	    /** 业务动作：在事务内执行并返回响应。 */
33	    @FunctionalInterface
34	    public interface Action {
35	        ApiResult run();
36	    }
37	
38	    @Repository
39	    public static class Store {
40	
41	        private final JdbcTemplate jdbc;
42	
43	        public Store(JdbcTemplate jdbc) {
44	            this.jdbc = jdbc;
45	        }
46	
47	        public Optional<Stored> find(String requestId) {
48	            return jdbc.query(
49	                            "SELECT fingerprint, response_status, response_body"
50	                                    + " FROM idempotency_record WHERE request_id = ?",
51	                            (rs, rowNum) -> new Stored(rs.getString(1),
52	                                    new ApiResult(rs.getInt(2), rs.getString(3))),
53	                            requestId)
54	                    .stream()
55	                    .findFirst();
56	        }
57	
58	        public void insert(String requestId, long rideId, String operation,
59	                String fingerprint, ApiResult result) {
60	            jdbc.update("INSERT INTO idempotency_record"
61	                            + " (request_id, ride_id, operation, fingerprint, response_status, response_body)"
62	                            + " VALUES (?, ?, ?, ?, ?, ?)",
63	                    requestId, rideId, operation, fingerprint, result.status(), result.body());
64	        }
65	
66	        record Stored(String fingerprint, ApiResult result) {
67	        }
68	    }
69	
70	    @Service
71	    public static class Executor {
72	
73	        private final Store store;
74	        private final TransactionTemplate tx;
75	        private final ObjectMapper objectMapper;
76	
77	        public Executor(Store store, TransactionTemplate tx, ObjectMapper objectMapper) {
78	            this.store = store;
79	            this.tx = tx;
80	            this.objectMapper = objectMapper;
81	        }
82	
83	        /**
84	         * 幂等执行：同键同参重放首次结果；同键异参抛 409；
85	         * 并发同键由主键约束兜底，失败方重读并按同参/异参处理。
86	         */
87	        public ApiResult execute(String requestId, String operation, long rideId,
88	                Object businessFields, Action action) {
89	            String fingerprint = fingerprint(requestId, businessFields);
90	            Optional<ApiResult> existing = findOrConflict(requestId, fingerprint);
91	            if (existing.isPresent()) {
92	                return existing.get();
93	            }
94	            try {
95	                return tx.execute(status -> {
96	                    ApiResult result = action.run();
97	                    store.insert(requestId, rideId, operation, fingerprint, result);
98	                    return result;
99	                });
100	            } catch (DuplicateKeyException e) {
101	                // 并发同键：主键约束兜底，重读并按同参/异参处理
102	                return findOrConflict(requestId, fingerprint)
103	                        .orElseThrow(() -> ApiException.conflict("幂等记录冲突，请重试"));
104	            } catch (ApiException e) {
105	                // 并发同键重放：本事务因首个请求已改变状态而失败时，返回首次结果
106	                return findOrConflict(requestId, fingerprint).orElseThrow(() -> e);
107	            }
108	        }
109	
110	        private Optional<ApiResult> findOrConflict(String requestId, String fingerprint) {
111	            Optional<Store.Stored> found = store.find(requestId);
112	            if (found.isEmpty()) {
113	                return Optional.empty();
114	            }
115	            Store.Stored stored = found.get();
116	            if (!stored.fingerprint().equals(fingerprint)) {
117	                throw new ApiException(HttpStatus.CONFLICT,
118	                        "requestId已存在但业务参数不一致，拒绝重放");
119	            }
120	            return Optional.of(stored.result());
121	        }
122	
123	        /**
124	         * 指纹 = SHA-256(结构化信封JSON)。
125	         * 信封将 requestId 作为JSON字符串独立编码、业务字段作为规范化JSON负载，
126	         * 键与负载边界无歧义：合法文本含分隔符（如 |、,、引号）也须区分为不同指纹。
127	         */
128	        public String fingerprint(String requestId, Object businessFields) {
129	            try {
130	                String payload = objectMapper.writeValueAsString(businessFields);
131	                String envelope = "{\"requestId\":"
132	                        + objectMapper.writeValueAsString(requestId)
133	                        + ",\"payload\":" + payload + "}";
134	                MessageDigest digest = MessageDigest.getInstance("SHA-256");
135	                byte[] hash = digest.digest(envelope.getBytes(StandardCharsets.UTF_8));
136	                return HexFormat.of().formatHex(hash);
137	            } catch (NoSuchAlgorithmException e) {
138	                throw new IllegalStateException(e);
139	            } catch (com.fasterxml.jackson.core.JsonProcessingException e) {
140	                throw new IllegalArgumentException("请求体无法序列化", e);
141	            }
142	        }
143	    }
144	}
