8	import jakarta.validation.constraints.NotEmpty;
9	import jakarta.validation.constraints.NotNull;
10	import jakarta.validation.constraints.Positive;
11	import jakarta.validation.constraints.Size;
12	
13	/**
14	 * API 请求与响应 DTO 集合。所有写操作请求均携带 requestId 用于幂等。
15	 */
16	public final class RideDtos {
17	
18	    private RideDtos() {
19	    }
20	
21	    /** 日检清单项。 */
22	    public record CheckItem(
23	            @NotBlank(message = "检查项名称不能为空") String itemName,
24	            @NotNull(message = "检查项合格标记不能为空") Boolean passed) {
25	    }
26	
27	    /** 创建设备请求（合成数据）；inspectionRequired 缺省为 false，旧设备行为不变。 */
28	    public record CreateRideRequest(
29	            @NotBlank(message = "设备名称不能为空") String name,
30	            @Positive(message = "载荷阈值必须为正数") int maxLoad,
31	            @Positive(message = "速度阈值必须为正数") int maxSpeed,
32	            Boolean inspectionRequired) {
33	
34	        /** 兼容旧入口：不携带受检标志时按未受检设备处理。 */
35	        public CreateRideRequest(String name, int maxLoad, int maxSpeed) {
36	            this(name, maxLoad, maxSpeed, null);
37	        }
38	    }
39	
40	    /** 日检请求：清单逐项合格方可试运行。 */
41	    public record DailyCheckRequest(
42	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId,
43	            @NotEmpty(message = "日检清单不能为空") List<@Valid CheckItem> items) {
44	    }
45	
46	    /** 试运行请求：normal=true 表示空载无异常。 */
47	    public record TrialRunRequest(
48	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId,
49	            @NotNull(message = "试运行结果不能为空") Boolean normal) {
50	    }
51	
52	    /** 开放请求。 */
53	    public record OpenRequest(
54	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId) {
55	    }
56	
57	    /** 安全装置失效上报：压杠、安全带与联锁装置任一失效整机立即停运。 */
58	    public record SafetyFaultRequest(
59	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId,
60	            @NotBlank(message = "安全装置名称不能为空") String device) {
61	    }
62	
63	    /** 复检请求：故障停机后复检合格方可复开。 */
64	    public record RecheckRequest(
65	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId,
66	            @NotEmpty(message = "复检清单不能为空") List<@Valid CheckItem> items) {
67	    }
68	
69	    /** 复开请求：同日复开最多2次。 */
70	    public record ReopenRequest(
71	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId) {
72	    }
73	
74	    /** 闭园归档请求：归档为终态，重复归档返回幂等成功。 */
75	    public record ArchiveRequest(
76	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId) {
77	    }
78	
79	    /** 运行监测读数（合成数据）。 */
80	    public record ReadingRequest(
81	            @NotNull(message = "载荷读数不能为空") Integer loadValue,
82	            @NotNull(message = "速度读数不能为空") Integer speedValue) {
83	    }
84	
85	    /**
86	     * 年度证书签发/换证请求（合成规则）。
87	     * passedAt 缺省为当前UTC时刻；validUntil 缺省为合格时刻+365×24小时，恰截止失效。
88	     */
89	    public record IssueCertificateRequest(
90	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId,
91	            Instant passedAt,
92	            Instant validUntil) {
93	    }
94	
95	    /** 证书撤销请求：携带 expectedVersion 乐观锁，版本从1开始、成功变更加1。 */
96	    public record RevokeCertificateRequest(
97	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId,
98	            @NotNull(message = "expectedVersion不能为空") @Positive(message = "expectedVersion必须为正数")
99	            Long expectedVersion,
100	            @Size(max = 256, message = "撤销原因最长256字符") String reason) {
101	    }
102	
103	    /** 大修登记请求：原子递增大修版本、暂停开放并使旧监督检验失效。 */
104	    public record OverhaulRequest(
105	            @NotBlank(message = "requestId不能为空") @Size(max = 64) String requestId) {
