23	    }
24	
25	    /** 登记一次大修，记录递增后的大修版本，返回记录ID。 */
26	    public long insertOverhaul(long rideId, String requestId, long overhaulVersion) {
27	        jdbc.update("INSERT INTO overhaul_record (ride_id, request_id, overhaul_version)"
28	                + " VALUES (?, ?, ?)", rideId, requestId, overhaulVersion);
29	        Long id = jdbc.queryForObject(
30	                "SELECT MAX(id) FROM overhaul_record WHERE ride_id = ?", Long.class, rideId);
31	        return id;
32	    }
33	
34	    /** 确认一次监督检验：绑定大修版本、两名检验人与全清单明细，返回检验ID。 */
35	    public long insertInspection(long rideId, String requestId, long overhaulVersion,
36	            String inspectorOne, String inspectorTwo, List<CheckItem> items) {
37	        boolean allPassed = items.stream().allMatch(CheckItem::passed);
38	        jdbc.update("INSERT INTO supervision_inspection"
39	                        + " (ride_id, request_id, overhaul_version, inspector_one, inspector_two, all_passed)"
40	                        + " VALUES (?, ?, ?, ?, ?, ?)",
41	                rideId, requestId, overhaulVersion, inspectorOne, inspectorTwo, allPassed);
42	        Long inspectionId = jdbc.queryForObject(
43	                "SELECT MAX(id) FROM supervision_inspection WHERE ride_id = ?",
44	                Long.class, rideId);
45	        for (CheckItem item : items) {
46	            jdbc.update("INSERT INTO supervision_inspection_item"
47	                            + " (inspection_id, item_name, passed) VALUES (?, ?, ?)",
48	                    inspectionId, item.itemName(), item.passed());
49	        }
50	        return inspectionId;
51	    }
52	
53	    /** 当前大修版本是否已有全清单合格的监督检验（开放资格证据）。 */
54	    public boolean existsConfirmed(long rideId, long overhaulVersion) {
55	        Integer count = jdbc.queryForObject(
56	                "SELECT COUNT(*) FROM supervision_inspection"
57	                        + " WHERE ride_id = ? AND overhaul_version = ? AND all_passed = TRUE",
58	                Integer.class, rideId, overhaulVersion);
59	        return count != null && count > 0;
60	    }
61	
62	    /** 设备全部监督检验记录（含明细），按确认顺序排列，可复算。 */
63	    public List<Map<String, Object>> listInspections(long rideId) {
64	        List<Map<String, Object>> inspections = jdbc.queryForList(
65	                "SELECT id, request_id, overhaul_version, inspector_one, inspector_two,"
66	                        + " all_passed, version, created_at"
67	                        + " FROM supervision_inspection WHERE ride_id = ? ORDER BY id", rideId);
68	        for (Map<String, Object> inspection : inspections) {
69	            long inspectionId = ((Number) inspection.get("id")).longValue();
70	            inspection.put("items", jdbc.queryForList(
71	                    "SELECT item_name, passed FROM supervision_inspection_item"
72	                            + " WHERE inspection_id = ? ORDER BY id", inspectionId));
73	        }
74	        return inspections;
75	    }
76	
77	    /** 设备全部大修登记记录，按登记顺序排列，可复算。 */
78	    public List<Map<String, Object>> listOverhauls(long rideId) {
79	        return jdbc.queryForList(
80	                "SELECT id, request_id, overhaul_version, created_at"
81	                        + " FROM overhaul_record WHERE ride_id = ? ORDER BY id", rideId);
82	    }
83	}
