package com.example.starter.ride;

/**
 * 检修挂牌单状态机：建档→启动（进行中）→结束。
 * 结束只清除挂牌阻断，不改变设备原状态链。
 */
public enum MaintenanceStatus {

    /** 已建档（初始状态），人员清单可查到但尚未冻结，未占用设备 */
    PREPARED,

    /** 进行中：整机已停运，人员清单冻结，每把锁待双人签认撤除 */
    IN_PROGRESS,

    /** 已结束：全部锁撤除后结束，仅清除挂牌阻断，不自动开放 */
    FINISHED
}

package com.example.starter.ride;

import java.time.Instant;

/**
 * 检修挂牌单实体（合成数据）。
 *
 * @param id         检修单主键
 * @param rideId     设备ID
 * @param status     检修单状态，见 {@link MaintenanceStatus}
 * @param version    单据版本号，从1开始，每次成功修改加1，修改须携带 expectedVersion
 * @param startedAt  启动检修时刻（UTC），NULL 表示未启动
 * @param finishedAt 结束检修时刻（UTC），NULL 表示未结束
 */
public record MaintenanceOrder(
        long id,
        long rideId,
        MaintenanceStatus status,
        long version,
        Instant startedAt,
        Instant finishedAt) {

    /** 挂牌人员上限：1至20名不同人员。 */
    public static final int MAX_PERSONNEL = 20;
}

package com.example.starter.ride;

import java.time.Instant;

/**
 * 检修挂牌锁实体：启动检修时为每名挂牌人员建立的唯一锁。
 *
 * @param id             挂牌锁主键
 * @param maintenanceId  检修单ID
 * @param personName     锁归属人员姓名，只能由本人与一名不同监护员共同确认撤除
 * @param removed        锁是否已撤除
 * @param removedAt      撤锁时刻（UTC），NULL 表示未撤锁
 */
public record MaintenanceLock(
        long id,
        long maintenanceId,
        String personName,
        boolean removed,
        Instant removedAt) {
}

